      Lemma vs_finish : forall msF m (sA : as_St H) mo (r : rv) (T ch : Z),
        as_AKREL H sA (mkCfg msF mo) -> as_MPRES H mo0 mo ->
        as_VIS H sA msF = MS (mkRr r) F (Z_to_bv 64 AOPDEL) fc None m (seg_rom asegs) ->
        rra r = Z_to_bv 64 0xf1668 -> ra0 r = Z_to_bv 64 Bg -> rsp r = spw -> rgp r = gp -> rtp r = tp -> rs0 r = a0 ->
        rs1 r = Z_to_bv 64 (Z.shiftr va 3) -> rs4 r = Z_to_bv 64 2147450880 ->
        rs7 r = s7 -> rs8 r = s8 -> rs9 r = s9 -> rs10 r = s10 -> rs11 r = s11 ->
        as_RHEAP H sA (BUFB :: REST) m -> vinv m -> addressable m Bg (24 * cap) ->
        vframe m spw s6 s5 s4 s3 s2 s1 s0 ra ->
        rw_cells asegs m va (hdr9 temp Bg T EE ch j7) -> 0 <= T < 2^64 -> 0 <= ch < 2^64 ->
        rw_cells asegs m Bg [CB (24 * n)%nat bs; CB (Z.to_nat (24 * (cap - Z.of_nat n))) junk] ->
        xpres H REST (bv_unsigned sp) (vs_X va) m0 m ->
        as_AL H sA >= as_AL H sA0 - cf_blocks H (flat_map blocks_item items) ->
        as_SR H POST (mkCfg msF mo).
Proof.
